package org.apache.commons.math.geometry;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.apache.commons.math.exception.MathArithmeticException;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.util.FastMath;
import org.apache.commons.math.util.MathUtils;
import org.apache.commons.math3.geometry.euclidean.threed.Vector3D;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for org.apache.commons.math.geometry.Vector3D.distance1
 */
public class Vector3D_distance1_TriageGen1Test {

    private static final double EPSILON = 1e-10;

    @Test
    public void testDistance1_SamePoint() {
        Vector3D v1 = new Vector3D(1.0, 2.0, 3.0);
        Vector3D v2 = new Vector3D(1.0, 2.0, 3.0);
        double expected = 0.0;
        double actual = Vector3D.distance1(v1, v2);
        Assert.assertEquals("Distance between same points should be 0", expected, actual, EPSILON);
    }

    @Test
    public void testDistance1_PositiveDifferences() {
        Vector3D v1 = new Vector3D(0.0, 0.0, 0.0);
        Vector3D v2 = new Vector3D(1.0, 2.0, 3.0);
        // |1-0| + |2-0| + |3-0| = 6
        double expected = 6.0;
        double actual = Vector3D.distance1(v1, v2);
        Assert.assertEquals("Distance calculation failed for positive differences", expected, actual, EPSILON);
    }

    @Test
    public void testDistance1_NegativeDifferences() {
        Vector3D v1 = new Vector3D(5.0, 5.0, 5.0);
        Vector3D v2 = new Vector3D(2.0, 8.0, 1.0);
        // |2-5| + |8-5| + |1-5| = |-3| + |3| + |-4| = 3 + 3 + 4 = 10
        double expected = 10.0;
        double actual = Vector3D.distance1(v1, v2);
        Assert.assertEquals("Distance calculation failed with negative coordinate differences", expected, actual, EPSILON);
    }

    @Test
    public void testDistance1_MixedCoordinates() {
        Vector3D v1 = new Vector3D(-1.5, 2.5, 0.0);
        Vector3D v2 = new Vector3D(1.5, -2.5, -1.0);
        // |1.5 - (-1.5)| + |-2.5 - 2.5| + |-1.0 - 0.0| = 3.0 + 5.0 + 1.0 = 9.0
        double expected = 9.0;
        double actual = Vector3D.distance1(v1, v2);
        Assert.assertEquals("Distance calculation failed with mixed positive/negative coordinates", expected, actual, EPSILON);
    }

    @Test
    public void testDistance1_LargeValues() {
        Vector3D v1 = new Vector3D(1e10, 1e10, 1e10);
        Vector3D v2 = new Vector3D(2e10, 2e10, 2e10);
        // |2e10 - 1e10| + |2e10 - 1e10| + |2e10 - 1e10| = 3e10
        double expected = 3e10;
        double actual = Vector3D.distance1(v1, v2);
        Assert.assertEquals("Distance calculation failed for large values", expected, actual, EPSILON);
    }

    @Test
    public void testDistance1_NaN() {
        Vector3D v1 = new Vector3D(Double.NaN, 0.0, 0.0);
        Vector3D v2 = new Vector3D(1.0, 1.0, 1.0);
        double actual = Vector3D.distance1(v1, v2);
        Assert.assertTrue("Distance with NaN should be NaN", Double.isNaN(actual));
    }

    @Test
    public void testDistance1_Infinity() {
        Vector3D v1 = new Vector3D(Double.POSITIVE_INFINITY, 0.0, 0.0);
        Vector3D v2 = new Vector3D(0.0, 0.0, 0.0);
        double actual = Vector3D.distance1(v1, v2);
        Assert.assertTrue("Distance with Infinity should be Infinity", Double.isInfinite(actual));
    }
}
